-- Đưa sequence của cột identity về sau id lớn nhất
SELECT setval(pg_get_serial_sequence('departments', 'id'), max(id)) FROM departments;
SELECT setval(pg_get_serial_sequence('majors', 'id'), max(id)) FROM majors;
SELECT setval(pg_get_serial_sequence('subjects', 'id'), max(id)) FROM subjects;
SELECT setval(pg_get_serial_sequence('rooms', 'id'), max(id)) FROM rooms;
SELECT setval(pg_get_serial_sequence('lecturers', 'id'), max(id)) FROM lecturers;
SELECT setval(pg_get_serial_sequence('lecturer_slots', 'id'), max(id)) FROM lecturer_slots;
SELECT setval(pg_get_serial_sequence('student_classes', 'id'), max(id)) FROM student_classes;
SELECT setval(pg_get_serial_sequence('students', 'id'), max(id)) FROM students;
SELECT setval(pg_get_serial_sequence('semesters', 'id'), max(id)) FROM semesters;
